SELECT * FROM public.piquins_productos WITH NO DATA;
ALTER TABLE public.piquins_respaldo_inventario_20261127 ENABLE ROW LEVEL SECURITY;
INSERT INTO public.piquins_respaldo_inventario_20261127
SELECT p.* FROM public.piquins_productos p
WHERE NOT EXISTS (SELECT 1 FROM public.piquins_respaldo_inventario_20261127);
